FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 177: probes: lofts through three profiles, a straight rise then an uneven change of profile. Generated by tools/fixtures/gen-batch-177.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Knot arrays, weights and control point matrices are typed: indexed, as std does, rather than iterated.
function numbersProbe(numbers) returns array
{
    var out = [];
    for (var i = 0; i < size(numbers); i += 1)
        out = append(out, roundToPrecision(numbers[i], 9));
    return out;
}

function bsplineProbe(s) returns map
{
    var b = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational };
    try
    {
        b.uKnots = numbersProbe(s.uKnots);
        b.vKnots = numbersProbe(s.vKnots);
    }
    catch (error)
    {
        b.knots = "failed";
    }
    try
    {
        const matrix = s.controlPoints;
        var rows = [];
        for (var i = 0; i < size(matrix); i += 1)
        {
            var points = [];
            for (var j = 0; j < size(matrix[i]); j += 1)
                points = append(points, round6(matrix[i][j]));
            rows = append(rows, points);
        }
        b.poles = rows;
    }
    catch (error)
    {
        b.poles = "failed";
    }
    return b;
}

// Each face of a body: its area, its surface's type, and for a B-spline its degrees, knots and poles.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            const s = evSurfaceDefinition(context, { "face" : face });
            entry["type"] = s.surfaceType;
            if (s is BSplineSurface)
                entry.bspline = bsplineProbe(s);
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Each edge of a body that isn't straight: its ends and middle, and for a B-spline its degree, knots, poles and
// weights.
function curveProbe(context is Context, body is Query) returns array
{
    var out = [];
    const edges = qOwnedByBody(body, EntityType.EDGE);
    for (var edge in evaluateQuery(context, qSubtraction(edges, qGeometry(edges, GeometryType.LINE))))
    {
        var entry = {};
        try
        {
            const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1], "arcLengthParameterization" : false });
            var points = [];
            for (var l in lines)
                points = append(points, round6(l.origin));
            entry.points = points;
        }
        catch (error)
        {
            entry.points = "failed";
        }
        try
        {
            const c = evCurveDefinition(context, { "edge" : edge });
            if (c is BSplineCurve)
            {
                entry.degree = c.degree;
                entry.rational = c.isRational;
                entry.knots = numbersProbe(c.knots);
                var poles = [];
                for (var i = 0; i < size(c.controlPoints); i += 1)
                    poles = append(poles, round6(c.controlPoints[i]));
                entry.poles = poles;
                if (c.isRational)
                    entry.weights = numbersProbe(c.weights);
            }
        }
        catch (error)
        {
            entry.curve = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// loft: a sheet through lines from x = -10 to 10 at z = 0 and 10 and from -12.5 to 12.5 at z = 20
export function c001(context is Context, id is Id)
{
    const p0 = newSketchOnPlane(context, id + "p0", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p0, "line1", { "start" : vector(-10, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skSolve(p0);
    const p1 = newSketchOnPlane(context, id + "p1", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p1, "line1", { "start" : vector(-10, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skSolve(p1);
    const p2 = newSketchOnPlane(context, id + "p2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p2, "line1", { "start" : vector(-12.5, 0) * millimeter, "end" : vector(12.5, 0) * millimeter });
    skSolve(p2);
    loft(context, id + "loft1", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceOperationType" : NewSurfaceOperationType.NEW, "wireProfilesArray" : [{ "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }, { "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }, { "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "p2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }], "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT });
    return { "faces" : faceProbe(context, qCreatedBy(id + "loft1", EntityType.BODY)), "area" : roundToPrecision(evArea(context, { "entities" : qOwnedByBody(qCreatedBy(id + "loft1", EntityType.BODY), EntityType.FACE) }) / millimeter ^ 2, 6) };
}

